#!/usr/bin/env bash
# Release notes and CHANGELOG.md from the Conventional Commits, generated by git-cliff:
#
#   release-notes.sh                    the changes since the last release (make release-notes)
#   release-notes.sh 0.2.0              the notes of v0.2.0: the commits after the previous release
#                                       tag, up to tag v0.2.0 or, while it doesn't exist, to HEAD
#   release-notes.sh --changelog 0.2.0  regenerates CHANGELOG.md with v0.2.0 as the newest release
#
# A version's notes are what the release pull request and the GitHub Release show, in Markdown
# without the version heading: the version's hand-written summary (docs/releases/vX.Y.Z.md) when
# it has one, the legal notice under "## Legal", then under "## Changes" its features, bug fixes
# and performance changes, each message once (cliff.notes.toml), folded in a <details> block.
# Without a version, it prints that list alone, unfolded. CHANGELOG.md lists every change of
# every release (cliff.toml). Every release tag must be present locally (git fetch --tags), and
# the changelog needs them all in HEAD's history, which merging main back into develop ensures.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
source "$here/env.sh"
source "$here/lib.sh"
source "$here/release-lib.sh"

usage="usage: release-notes.sh [x.y.z] | release-notes.sh --changelog <x.y.z>"
changelog=false
if [ "${1:-}" = --changelog ]; then
  changelog=true
  shift
  [ $# -eq 1 ] || fxm_die "$usage"
fi
[ $# -le 1 ] || fxm_die "$usage"
version=${1:-}
tag=
if [ -n "$version" ]; then
  fxm_release_require_version "$version"
  tag=v$version
fi

"$here/install-git-cliff.sh" >/dev/null

if $changelog; then
  fxm_release_cliff cliff.toml --tag "$tag" --output CHANGELOG.md
  fxm_info "CHANGELOG.md regenerated with $tag"
  exit 0
fi

# The release's commits: from the closest older release tag (none before the first release) to
# the tag, or to HEAD while the tag doesn't exist yet.
end=
if [ -n "$tag" ]; then
  end=$(git -C "$FXM_ROOT" rev-parse -q --verify "refs/tags/$tag^{commit}") || end=
fi
if [ -z "$end" ]; then end=$(git -C "$FXM_ROOT" rev-parse HEAD); fi
# --exclude with the version's own tag, or with a pattern no tag has when there is no version.
previous=$(git -C "$FXM_ROOT" describe --tags --abbrev=0 --match 'v[0-9]*.[0-9]*.[0-9]*' \
  --exclude "${tag:-/}" "$end" 2>/dev/null) || previous=
range=$end
if [ -n "$previous" ]; then range=$previous..$end; fi

# The generated list, without the version heading and the blank lines around it.
changes() {
  if [ -n "$tag" ]; then
    fxm_release_cliff cliff.notes.toml --strip all --tag "$tag" "$range"
  else
    fxm_release_cliff cliff.notes.toml --strip all "$range"
  fi | awk 'done { print; next } /^## / { done = 1 }' | sed '/./,$!d'
}

if [ -z "$version" ]; then
  changes
  exit 0
fi

list=$(changes)
if fxm_release_has_summary "$version"; then
  # The summary without the blank lines around it.
  sed '/[^[:space:]]/,$!d' "$FXM_ROOT/$(fxm_release_summary_file "$version")" |
    awk '/[^[:space:]]/ { for (; blank > 0; blank--) print ""; print; next } { blank++ }'
  echo
fi
# The notes name the services FXM works with, so they carry its non-affiliation notice
# (docs/LEGAL.md, "Notice": change it there, in the README and on the disclaimer page too), and
# say where the source of the LGPL ffmpeg core in the web zip is (tools/ffmpeg-wasm/README.md,
# "The LGPL"). Both come before the list, the part that fxm_release_fit cuts when the notes are
# too long.
cat <<'EOF'
## Legal

FXM is an independent open-source project, not affiliated with or endorsed by YouTube, Google, Spotify or any other service it works with, and it hosts no music. You are responsible for following the terms of the services you use with FXM and the laws where you live. The [disclaimer](https://fxmusic.pages.dev/disclaimer) and the [privacy page](https://fxmusic.pages.dev/privacy) have the details.

EOF
echo "The web app converts downloads with FXM's build of FFmpeg (LGPL-2.1-or-later), LAME (LGPL)" \
  "and Opus (BSD). Their licences and notices are in the [third-party" \
  "notices](https://fxmusic.pages.dev/third-party-notices.txt), and the source it was built" \
  "from comes with every copy: in \`source/ffmpeg-core/\` of the web zip and on the site, and" \
  "as \`fxm-ffmpeg-core-source-$version.zip\` in the release."
cat <<'EOF'

## Changes

EOF
entries=$(grep -c '^- ' <<<"$list" || true)
if [ "$entries" -eq 0 ]; then
  printf '%s\n' "$list"
  exit 0
fi
# The list comes from commit subjects, so it is long and written for developers: folded, it
# leaves the summary and the release's files in view.
since="since ${previous:-the project started}"
echo "The features, bug fixes and performance changes $since, as their commit messages" \
  "describe them. Some may be in parts of FXM that aren't released yet."
echo
if [ "$entries" -eq 1 ]; then count="1 change"; else count="$entries changes"; fi
printf '<details>\n<summary>%s</summary>\n\n%s\n\n</details>\n' "$count" "$list"
